//! Data analysis functions (`datafun`) against values recorded from MATLAB R2023b. Each case is
//! an expression and MATLAB's result as `class dims values` (complex values as `re imi` pairs,
//! printed with %.17g), or `ERR message`.

use livre_lang::{Interpreter, OutputKind, Value};

fn same(a: f64, b: f64) -> bool {
    a == b || (a.is_nan() && b.is_nan()) || (a - b).abs() <= 1e-9 * a.abs().max(b.abs()) + 1e-12
}

fn num(tok: &str) -> f64 {
    match tok.trim_end_matches('i') {
        "NaN" => f64::NAN,
        "Inf" => f64::INFINITY,
        "-Inf" => f64::NEG_INFINITY,
        t => t.parse().unwrap_or_else(|_| panic!("bad number {tok}")),
    }
}

fn check(expr: &str, want: &str) -> Result<(), String> {
    let mut it = Interpreter::new();
    let _ = it.run_source(&format!("x = {expr};"));
    let errors: Vec<String> = it
        .take_outputs()
        .into_iter()
        .filter_map(|o| match o.kind {
            OutputKind::Error(e) => Some(e),
            _ => None,
        })
        .collect();
    if let Some(msg) = want.strip_prefix("ERR ") {
        return match errors.first() {
            Some(e) if e == msg => Ok(()),
            other => Err(format!("{expr}: expected error {msg:?}, got {other:?}")),
        };
    }
    if let Some(e) = errors.first() {
        return Err(format!("{expr}: unexpected error {e:?}"));
    }
    let mut toks = want.split(' ');
    let class = toks.next().unwrap();
    let dims = toks.next().unwrap();
    let vals: Vec<&str> = toks.collect();
    let m = match it.get_var("x") {
        Some(Value::Num(m)) => m.clone(),
        other => return Err(format!("{expr}: got {other:?}")),
    };
    let got_dims: String = m.dims.iter().map(|d| format!("{d}x")).collect();
    if m.kind.name() != class || got_dims != dims {
        return Err(format!("{expr}: got {} {got_dims}, MATLAB {class} {dims}", m.kind.name()));
    }
    let complex = vals.iter().any(|t| t.ends_with('i'));
    if complex != m.is_complex() && m.numel() > 0 {
        return Err(format!("{expr}: complexity differs (MATLAB complex: {complex})"));
    }
    for k in 0..m.numel() {
        let (re, im) = if complex { (num(vals[2 * k]), num(vals[2 * k + 1])) } else { (num(vals[k]), 0.0) };
        if !same(m.data[k], re) || !same(m.im_at(k), im) {
            return Err(format!("{expr}: element {} is {} {}i, MATLAB {re} {im}i", k + 1, m.data[k], m.im_at(k)));
        }
    }
    Ok(())
}

fn run_all(cases: &[(&str, &str)]) {
    let failures: Vec<String> = cases.iter().filter_map(|(e, w)| check(e, w).err()).collect();
    assert!(failures.is_empty(), "{} of {} cases differ:\n{}", failures.len(), cases.len(), failures.join("\n"));
}

#[test]
fn fourier_filtering_convolution_and_correlation() {
    run_all(CASES_A);
}

#[test]
fn moving_statistics_percentiles_topk_and_derivatives() {
    run_all(CASES_B);
}

#[test]
fn missing_data_outliers_smoothing_and_normalization() {
    run_all(CASES_C);
}

#[test]
fn change_points_extrema_binning_and_error_metrics() {
    run_all(CASES_DP6);
}

#[test]
fn grouping() {
    run_all(CASES_DP8);
}

